 function questCards(){const cards=portEventCard()+(E.japoriQuest(s).status===1?japoriCard():'')+(s.jarekStatus===1?jarekCard():'')+(s.moonBought?moonCard():'')+campaignCards();return `<div class="quest-list">${cards||'<section class="panel"><h2>Quests</h2><p>'+esc(D.text.screen_status_quests_default)+'</p></section>'}</div>`;}
