 function specialDialog(){const p=s.pending;if(p.step==='complete')return `<section class="panel" aria-label="Port event result"><div class="eyebrow">Special event result</div><h2>${esc(p.title)}</h2><p>${esc(p.text)}</p><button class="primary continue" data-special="yes">Continue</button></section>`;const q=p.quote;return `<section class="panel" aria-label="Port event decision"><div class="eyebrow">Special event · ${esc(s.systems[s.current].name)}</div><h2>${esc(C.eventName(s,q.id))}</h2><p>${esc(C.eventText(s,q.id))}</p>${q.price?`<div class="kv"><span>${q.price<0?'Reward':'Cost'}</span><strong>${num(Math.abs(q.price))} credits</strong></div>`:''}${q.wildLeaves?'<p class="notice">Accepting the reactor makes Wild leave, closing his assignment.</p>':''}${q.id==='GETREACTOR'?'<p class="notice">Requires fifteen empty bays. The reactor has a travel deadline and increases damage from enemy attacks.</p>':''}${q.id==='TRANSPORTWILD'?'<p class="notice">Wild needs one spare quarter and a Beam laser or stronger weapon. Police inspection leads to arrest.</p>':''}${q.blocked?`<p class="notice">${esc(q.blocked)}</p>`:''}<div class="service"><button data-special="no">Not now</button><button class="primary" data-special="yes" ${q.blocked?'disabled':''}>${D.specialEvents.find(e=>e.id===q.id).justAMessage?'Continue':'Accept event'}</button></div></section>`;}
