 function encounter(e=s.encounter,backdrop=false){if(!e)return '';const kind=e.kind||'PIRATE',target=s.trip?.target??lastEncounter?.target??s.current,clicks=s.trip?.clicks??lastEncounter?.clicks??0,t=D.ships.find(x=>x.id===e.opponent.type),captain=F.trades[e.rare],rare=['BOTTLE','MARIECELESTE'].includes(kind)||kind==='FAMOUSCAPTAIN'&&e.state==='IGNORE',actor=kind==='FAMOUSCAPTAIN'?captain.name:kind==='BOTTLE'?'floating bottle':kind==='MARIECELESTE'?'the abandoned Marie Celeste':kind==='MANTIS'?'an alien Mantis':kind.toLowerCase()+' '+t.label.toLowerCase(),description=`At ${clicks} clicks from ${s.systems[target].name}, you encounter ${kind==='FAMOUSCAPTAIN'||kind==='MARIECELESTE'||kind==='MANTIS'?actor:'a '+actor}.`,status=kind==='BOTTLE'?D.text.opponentaction_bottle:kind==='MARIECELESTE'?D.text.opponentaction_marieceleste:captain&&e.state==='IGNORE'?D.text.opponentaction_meetcaptain:e.state==='ATTACK'?(kind==='POLICE'&&!e.round&&s.policeScore>-10?D.text.opponentaction_hailsurrender:D.text.opponentaction_attack):e.state==='FLEE'?D.text.opponentaction_flee:e.state==='SURRENDER'?D.text.opponentaction_surrender:['BUY','SELL'].includes(e.state)?D.text.opponentaction_trade:e.state==='INSPECTION'?(e.postMarie?D.text.opponentaction_postmarie:D.text.opponentaction_inspection):E.cloaked(s.ship,e.opponent,s.difficulty)?D.text.opponentaction_cloaked:D.text.opponentaction_ignore,icon=kind==='POLICE'?'police':kind==='TRADER'?'trader':kind==='PIRATE'?'pirate':null;
  let buttons=[];const button=(action,text)=>`<button data-combat="${action}">${text}</button>`;
  if(rare){buttons=kind==='BOTTLE'?[button('drink','Drink'),button('continue','Ignore')]:kind==='MARIECELESTE'?[button('board','Board'),button('continue','Ignore')]:[button('attack','Attack'),button('continue','Ignore'),button('meet','Meet')];}
  else if(e.state==='ATTACK'){buttons=[button('attack','Attack'),button('flee','Flee')];if(['POLICE','PIRATE','MANTIS','SCARAB'].includes(kind))buttons.push(button('surrender','Surrender'));}
  else if(e.state==='INSPECTION'){buttons=[button('attack','Attack'),button('flee','Flee'),button('submit',e.postMarie?'Yield':'Submit')];buttons.push(button('bribe','Bribe'));}
  else {buttons=[button('attack','Attack'),button('continue','Ignore')];if(['BUY','SELL'].includes(e.state))buttons.push(button('trade','Trade'));if(e.state==='SURRENDER'&&['PIRATE','TRADER'].includes(kind))buttons.push(button('plunder','Plunder'));}
  const shipText=(ship,max,header)=>{const t2=D.ships.find(x=>x.id===ship.type),total=ship.shields.filter(Boolean).reduce((n,id)=>n+D.shields.find(h=>h.id===id).power,0),cur=ship.shieldStrength.reduce((a,b)=>a+b,0);return `<div>${encounterStyle==='textual'?`<b>${esc(header)}</b>`:''}<p>${esc(t2.label)}</p><p>${fmtText(D.text.screen_encounter_hull,[Math.trunc(ship.hull*100/max)])}</p><p>${total?fmtText(D.text.screen_encounter_shields,[Math.trunc(cur*100/total)]):esc(D.text.screen_encounter_noshields)}</p></div>`;};
  const statsText=encounterStyle!=='graphical'?`<div class="encounter-text">${shipText(s.ship,E.hullMaximum(s),D.text.screen_encounter_playership_header)}${shipText(e.opponent,t.hullStrength,D.text.screen_encounter_enemyship_header)}</div>`:'';
  const stats=false?`<div class="encounter-stats"><div>Your ship: ${esc(s.ship.type)}<br>Hull: ${Math.trunc(s.ship.hull*100/E.hullMaximum(s))}%<br>Shields: ${s.ship.shieldStrength.reduce((a,b)=>a+b,0)}</div><div>${esc(t.label)}<br>Hull: ${Math.trunc(e.opponent.hull*100/t.hullStrength)}%<br>Shields: ${e.opponent.shieldStrength.reduce((a,b)=>a+b,0)}</div></div>`:'';
  return `<section class="panel native-encounter" aria-label="Encounter"><h2>Encounter</h2>${encounterStyle==='textual'?'':`<div class="encounter-icon">${icon?`<img src="${ASSETS[icon]}" alt="${kind.toLowerCase()}">`:''}</div>`}${encounterStyle!=='textual'?`<div class="encounter-ships">${shipPicture(s.ship)}${shipPicture(e.opponent,true)}</div>`:''}${statsText}${stats}<p class="encounter-description">${esc(description)}</p><p class="encounter-action">${esc(status)}</p><div class="combat-actions">${buttons.join('')}</div>${combatRunning&&!backdrop?'<div class="continuous-controls"><button data-stop-combat>Interrupt</button></div>':''}${e.lastRound?`<div class="combat-feedback" aria-live="polite">${esc(e.lastRound)}</div>`:''}${kind==='SCARAB'?'<details class="encounter-notes"><summary>Combat notes</summary>Only Pulse and Morgan’s lasers can damage the Scarab.</details>':''}</section>`;
 }

 // Original action-mode menu: menu_action_mode_dropdowns.xml with menu/command.xml, game.xml and help.xml.
 const commands=[['buy','B'],['sell','S'],['yard','Y'],['buyeq','E'],['selleq','Q'],['personnel','P'],['bank','K'],['info','I'],['status','C'],['chart','G'],['warp','W']];
 const commandKey=id=>commands.find(c=>c[0]===id)[1];
 const helpTopics={helponmenu:'help_helponmenu',howtoplay:'help_howtoplay',trading:'help_trading',traveling:'help_travelling',shipequipment:'help_shipequipment',skills:'help_skills',firststeps:'help_firststeps',acknowledgements:'help_acknowledgements'};
 let shortcuts=['buy','sell','yard','warp'];
 try{const saved=JSON.parse(localStorage.getItem('space-trader-shortcuts-v1')||'null');if(Array.isArray(saved)&&saved.length===4&&saved.every(id=>commands.some(c=>c[0]===id)))shortcuts=saved;}catch{}
 function docked(){return tab!=='title'&&!s.trip&&!s.encounter&&!s.ended;}
 // ScreenType: every screen except TITLE, ENDGAME and ENCOUNTER is "docked".
 const dockedTypes=new Set(['BUY','SELL','YARD','BUYEQ','SELLEQ','PERSONNEL','BANK','INFO','STATUS','CHART','WARP','BUYSHIP','QUESTS','SHIP','CARGO','TARGET','AVGPRICES']);
 const tabTypes={buy:'BUY',sell:'SELL',yard:'YARD',crew:'PERSONNEL',bank:'BANK',info:'INFO',status:'STATUS',ships:'BUYSHIP',quests:'QUESTS',ship:'SHIP',cargo:'CARGO'};
 const typeCommands={BUY:'buy',SELL:'sell',YARD:'yard',BUYEQ:'buyeq',SELLEQ:'selleq',PERSONNEL:'personnel',BANK:'bank',INFO:'info',STATUS:'status',CHART:'chart',WARP:'warp'};
 function screenType(){if(tab==='title')return 'TITLE';if(s.ended)return 'ENDGAME';if(s.trip||s.encounter)return 'ENCOUNTER';if(selected!==null)return targetPrices?'AVGPRICES':'TARGET';if(tab==='equipment')return equipmentMode==='sell'?'SELLEQ':'BUYEQ';if(tab==='chart')return chartMode==='galaxy'?'CHART':'WARP';return tabTypes[tab]||'TAB:'+tab;}
 const isDocked=t=>dockedTypes.has(t)||String(t).startsWith('TAB:');
 // MainActivity.setCurrentScreenType(type, addToBackStack): going from one docked screen to another docked screen
 // pushes the previous one; any other change of screen clears the stack. A pop (onBackPressed) neither pushes nor
 // clears. Arrival (GameState: setCurrentScreenType(INFO); clearBackStack()) and New Game clear it as well.
 function trackScreens(){
   const t=screenType(),k=s.days+':'+s.current;if(selected!==null)warpSystem=selected;
   if(stackOwner!==s){stackOwner=s;backStack=(Array.isArray(s.ui?.backStack)?s.ui.backStack:[]).filter(x=>x&&isDocked(x.type)).map(x=>({type:String(x.type),...(Number.isInteger(x.selected)?{selected:x.selected}:{})}));prevType=t;travelKey=k;settling=false;popping=false;syncHistory();return;}
   if(k!==travelKey){travelKey=k;settling=true;}
   if(settling){backStack=[];if(docked()&&!s.pending&&!quantity)settling=false;}
   else if(t!==prevType&&!popping){if(isDocked(t)&&isDocked(prevType))backStack.unshift({type:prevType,...(prevType==='TARGET'||prevType==='AVGPRICES'?{selected:warpSystem}:{})});else backStack=[];}
   prevType=t;popping=false;syncHistory();
 }
 // While "Prev. screen with back button" is on, one history entry per back-stack screen lets the browser/Android back
 // button reach onBackPressed (popstate). Entries are only added during a user action, so the browser does not skip them.
 function syncHistory(){if(rewinding)return;const want=s.options?.recallScreens?backStack.length:0;
   try{if(histDepth>want){rewinding=true;const n=want-histDepth;histDepth=want;setTimeout(()=>{rewinding=false;},1000);history.go(n);return;}
     while(histDepth<want&&navigator.userActivation?.isActive!==false)history.pushState({stDepth:++histDepth},'');}catch{}}
 // MainActivity.onBackPressed: finish the menu action mode; else, with the option on, show the screen popped from the
 // back stack. (On Android an open dialog takes the back key itself and is dismissed; here overlay and quantity dialogs close the same way as on Escape, and game-flow dialogs (s.pending) stay.) With the
 // option off or the stack empty the original asks "Exit"; here no history entry is left, so the browser leaves the page.
 function backPressed(){if(menu){if(menu.drop)menu.drop=null;else menu=null;return;}if(overlay||quantity){overlay=null;quantity=null;return;}if(s.pending||!s.options?.recallScreens||!backStack.length)return;const x=backStack.shift();popping=true;showScreenType(x.type,x.selected);}
 function showScreenType(t,sel){if(typeCommands[t]){goCommand(typeCommands[t]);return;}menu=null;overlay=null;mapHole=null;
   if(t==='TARGET'||t==='AVGPRICES'){const id=warpSystem??sel;if(Number.isInteger(id)&&s.systems[id]&&id!==s.current){selected=id;targetPrices=t==='AVGPRICES';}return;}
   selected=null;tab=Object.keys(tabTypes).find(k=>tabTypes[k]===t)||(t.startsWith('TAB:')?t.slice(4):tab);}
 window.addEventListener('popstate',event=>{const d=Number.isInteger(event.state?.stDepth)?event.state.stDepth:0,back=histDepth-d;histDepth=d;
   if(rewinding){rewinding=false;syncHistory();return;}
   action(()=>{for(let i=0;i<back;i++)backPressed();});});
 // footer_shortcuts (activity_main.xml; MainActivity.onCreate and refreshExtraShortcuts): one equal-width monospace
 // ShortcutButton per dropdown screen, in dropdown order, shown on docked screens while "Extra shortcuts in footer" is on.
 const footer=document.createElement('nav');footer.id='footer-shortcuts';footer.className='footer-shortcuts';footer.hidden=true;footer.setAttribute('aria-label','Footer shortcuts');
 footer.innerHTML=commands.map(([id,k])=>`<button data-command="${id}" aria-label="${esc(D.text['screen_'+id])}">${k}</button>`).join('');document.querySelector('.app').append(footer);
 // ShortcutButton.onLongClick: Toast.LENGTH_SHORT with the screen's full title, bottom centre, raised by the button height
 // (system toast look measured in the emulator: #dcdcdc pill, #1d1d1d 14sp text). A long press does not click the button.
 let footerPress=null,footerLong=false,toastTimer=null;
 function showToast(text){let el=document.getElementById('st-toast');if(!el){el=document.createElement('div');el.id='st-toast';el.setAttribute('role','status');document.body.append(el);}clearTimeout(toastTimer);
   el.textContent=text;el.style.bottom=footer.offsetHeight+'px';el.classList.remove('on');void el.offsetWidth;el.classList.add('on');toastTimer=setTimeout(()=>el.classList.remove('on'),2000);}
 footer.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!b)return;footerLong=false;clearTimeout(footerPress);footerPress=setTimeout(()=>{footerPress=null;footerLong=true;showToast(D.text['screen_'+b.dataset.command]);},500);});
 for(const type of ['pointerup','pointercancel','pointerleave'])footer.addEventListener(type,()=>{clearTimeout(footerPress);footerPress=null;});
 footer.addEventListener('contextmenu',e=>e.preventDefault());
 footer.addEventListener('click',e=>{if(footerLong){footerLong=false;e.stopPropagation();e.preventDefault();}},true);
 function renderFooter(){footer.hidden=!(s.options?.extraShortcuts&&isDocked(screenType()));document.body.classList.toggle('has-footer',!footer.hidden);}
 // GameState.animateAttack / animateEnterExit (res/anim/*.xml, keyframes in style.css), only with "Animate encounters".
 // The red hit flash is the original's SRC_ATOP colour filter: an SVG feFlood composited "atop" the ship.
 document.body.insertAdjacentHTML('beforeend','<svg class="st-filters" width="0" height="0" aria-hidden="true" focusable="false" style="position:absolute;width:0;height:0;overflow:hidden">'+['player','opponent'].map(k=>`<filter id="st-flash-${k}" color-interpolation-filters="sRGB"><feFlood id="st-flood-${k}" flood-color="#f00" flood-opacity="0"/><feComposite in2="SourceGraphic" operator="atop"/></filter>`).join('')+'</svg>');
 const shipAnimTime={'enter-left':600,'enter-right':600,'exit-left':400,'exit-right':400,'hit-player':200,'hit-opponent':200,'miss-player':550,'miss-opponent':550,'destroyed-player':1275,'destroyed-opponent':1275};
 const shipPoints=sh=>sh.hull+(sh.shieldStrength||[]).reduce((a,b)=>a+(b||0),0);
 // An animation's end effect (onAnimationEnd) also applies when another one replaces it (clearAnimation).
 function endShipAnim(k){const a=shipAnim[k];shipAnim[k]=null;if(!a)return;if(a.name.startsWith('enter'))offScreen[k]=false;else if(a.name.startsWith('exit'))offScreen[k]=true;else if(a.name.startsWith('destroyed'))shipGone[k]=true;}
 function startShipAnim(k,name){endShipAnim(k);shipAnim[k]={name,start:performance.now()};}
 function shipAttack(k,hit,destroyed){startShipAnim(k,(destroyed?'destroyed-':hit?'hit-':'miss-')+k);if(hit){shipFlash[k]=performance.now();const f=document.getElementById('st-flood-'+k);if(f){f.classList.remove('on');void getComputedStyle(f).floodOpacity;f.classList.add('on');}}}
 function combatBefore(){const e=s.encounter;return e?{e,ship:s.ship,round:e.round||0,state:e.state,ps:shipPoints(s.ship),os:shipPoints(e.opponent)}:null;}
 // GameState.executeAction: the commander's ship animates when the opponent fires (attack states only), the opponent's
 // when the commander fires (not when fleeing); a hit lowers shields or hull. Escapes play the exit animations.
 function combatAfter(b){if(!b||!s.options?.encounterAnim||(b.e.round||0)===b.round)return;const e=b.e,kind=e.kind||'PIRATE',fleeing=/you try to escape\.$/.test(e.lastRound||''),shipHit=shipPoints(b.ship)<b.ps,opponentHit=shipPoints(e.opponent)<b.os;
   // State the opponent was in when the round was fought (the engine's performEncounter changes before the round).
   let st=b.state;
   if(!fleeing&&(kind==='FAMOUSCAPTAIN'||kind==='POLICE'&&['IGNORE','INSPECTION'].includes(st)||kind==='PIRATE'&&st==='IGNORE'))st='ATTACK';
   if(fleeing&&kind==='POLICE'&&st==='INSPECTION')st='ATTACK';
   if(!fleeing&&kind==='TRADER'&&st!=='FLEE')st=e.state==='ATTACK'||opponentHit&&(e.opponent.weapons||[]).some(Boolean)?'ATTACK':e.state;
   if(shipHit||st==='ATTACK')shipAttack('player',shipHit,b.ship.hull<=0);
   if(!fleeing)shipAttack('opponent',opponentHit,e.opponent.hull<=0);
   const t=s.pending?.kind==='result'?s.pending.title:null;
   if(t===D.text.screen_encounter_escaped_title)startShipAnim('player','exit-left');else if(t===D.text.screen_encounter_opponentescaped_title)startShipAnim('opponent','exit-right');}
 function drawShipAnims(){
   if(s.encounter&&s.encounter!==shownEncounter){shownEncounter=s.encounter;endShipAnim('player');endShipAnim('opponent');shipGone={player:false,opponent:false};
     // GameState.drawEncounterForm: the opponent flies in; the commander's ship too if it left the previous encounter.
     if(s.options?.encounterAnim){startShipAnim('opponent','enter-right');if(offScreen.player)startShipAnim('player','enter-left');}}
   const now=performance.now();let next=Infinity;
   for(const k of ['player','opponent']){
     let a=shipAnim[k];if(a&&now-a.start>=shipAnimTime[a.name]){endShipAnim(k);a=null;}
     if(a)next=Math.min(next,a.start+shipAnimTime[a.name]-now);
     const flashing=now-shipFlash[k]<200;if(flashing)next=Math.min(next,shipFlash[k]+200-now);
     const el=$('screen').querySelector('.encounter-ships .ship-sprite'+(k==='opponent'?'.opponent':':not(.opponent)'));if(!el)continue;
     if((el.dataset.stAnim||'')!==(a?a.name+'@'+a.start:'')){for(const c of [...el.classList])if(/^st-(enter|exit|hit|miss|destroyed)-/.test(c))el.classList.remove(c);
       if(a){void el.offsetWidth;el.style.setProperty('--st-delay',(a.start-now)+'ms');el.classList.add('st-'+a.name);el.dataset.stAnim=a.name+'@'+a.start;}else{el.style.removeProperty('--st-delay');delete el.dataset.stAnim;}}
     el.classList.toggle('st-flash-'+k,flashing);
     // showShip: a ship that flew off (commanderOffScreen/opponentOffScreen) or was destroyed stays invisible.
     el.classList.toggle('st-hidden',!(a&&/^(enter|exit)/.test(a.name))&&(offScreen[k]||shipGone[k]));
   }
   clearTimeout(shipTimer);shipTimer=next<Infinity?setTimeout(drawShipAnims,next+20):null;}
 function goCommand(id){menu=null;overlay=null;selected=null;mapHole=null;if(id==='buyeq'||id==='selleq'){tab='equipment';equipmentMode=id==='buyeq'?'buy':'sell';}else if(id==='chart'||id==='warp'){tab='chart';chartMode=id==='chart'?'galaxy':'local';}else tab=id==='personnel'?'crew':id;}
 function menuItems(drop){
   if(drop==='command')return [...commands.map(([id,k])=>({id,text:D.text['command_dropdown_'+id],key:k})),...(EXTRAS.commandExtras?[{id:'ship',text:'Ship'},{id:'quests',text:'Quests'},{id:'log',text:'Journal'}]:[])];
   if(drop==='game')return [{id:'new',text:D.text.menu_new},{id:'switch',text:D.text.menu_switch},...(docked()?[{id:'retire',text:D.text.menu_retire}]:[]),'-',{id:'options',text:D.text.menu_options,key:'O'},{id:'shortcuts',text:D.text.menu_shortcuts},'-',{id:'scores',text:D.text.menu_scores},{id:'clearscores',text:D.text.menu_clearscores},'-',{id:'export',text:'Export Save'},{id:'import',text:'Import Save'}];
   return [{id:'current',text:D.text.menu_help_current,key:'H'},{id:'helponmenu',text:D.text.menu_help_helponmenu},'-',...['howtoplay','trading','traveling','shipequipment','skills','firststeps','acknowledgements'].map(id=>({id,text:D.text['menu_help_'+id]})),'-',{id:'about',text:D.text.menu_help_about}];
 }
 function renderMenu(){
   const bar=$('menu-bar');bar.hidden=!menu;if(!menu){bar.innerHTML='';return;}
   const spinner=id=>`<button class="menu-spinner${id==='help'?' menu-help':''}" data-menu-drop="${id}" aria-expanded="${menu.drop===id}" aria-label="${esc(D.text['menu_'+id])}"><span>${esc(D.text['menu_'+id])}</span></button>`;
   bar.innerHTML=`<button class="menu-close" data-menu-close aria-label="Done"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.41-1.41L7.83 13H20v-2z"/></svg></button>${docked()?spinner('command'):''}${spinner('game')}${spinner('help')}${menu.drop?`<div class="menu-dropdown" role="menu">${menuItems(menu.drop).map(item=>item==='-'?'<div class="menu-divider" role="separator"></div>':`<button role="menuitem" data-menu-item="${menu.drop}:${item.id}"><span>${esc(item.text)}</span><kbd>${item.key||''}</kbd></button>`).join('')}</div>`:''}`;
   const list=bar.querySelector('.menu-dropdown'),anchor=bar.querySelector(`[data-menu-drop="${menu.drop}"]`);
   if(list&&anchor)list.style.left=Math.max(0,Math.min(anchor.offsetLeft,bar.clientWidth-list.offsetWidth))+'px';
 }
 function box(title,message,help,buttons=[[D.text.generic_ok]]){dialogBox={title,message,help,buttons};overlay='box';}
 function boxDialog(){const b=dialogBox;return `<section class="panel dialog native-box"><h2>${esc(b.title)}</h2><p>${esc(b.message)}</p><div class="native-buttons">${b.buttons.map(([text],i)=>`<button data-box="${i}">${esc(text)}</button>`).join('')}</div></section>`;}
 function confirmBox(title,message,help,yes){box(title,message,help,[[D.text.generic_no],[D.text.generic_yes,yes]]);}
 function gameStarted(text){try{return JSON.parse(text)?.ui?.tab!=='title';}catch{return false;}}
 function switchGame(){
   persist();const other=slot===1?2:1;let saved=null;try{saved=localStorage.getItem(slotKey(other));}catch{}
   slot=other;try{localStorage.setItem(slotPref,String(slot));}catch{}
   selected=null;quantity=null;lastEncounter=null;paperRead=null;
   if(saved&&gameStarted(saved)){const prev=s;s=E.deserialize(saved);if(s.options?.sharePreferences??true){s.options={...prev.options};s.autoFuel=prev.autoFuel;s.autoRepair=prev.autoRepair;s.reserveMoney=prev.reserveMoney;s.leaveEmpty=Math.min(prev.leaveEmpty||0,E.cargoCapacity(s));}hasSaved=true;restoreUI();box(D.text.dialog_switched_title,D.text.dialog_switched_message.replace('%s',s.commanderName||''),'help_switched');return;}
   s=E.newGame();s.commanderName=D.text[other===1?'name_commander':'name_commander2'];hasSaved=false;tab='title';mapFocus=s.current;tracked=null;
   box(D.text.dialog_switchtonew_title,D.text.dialog_switchtonew_message,'help_switchtonew',[[D.text.generic_ok,()=>{prepareCommander();}]]);
 }
 function exportSave(){const blob=new Blob([E.serialize(s)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='space-trader-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function runMenu(drop,id){
   menu=null;
   if(drop==='command'){action(()=>goCommand(id));return;}
   if(drop==='help'){helpReturn=null;helpTopic=id==='current'?screenName():helpTopics[id];overlay=id==='about'?'about':'help';render();return;}
   if(id==='new'){if(tab==='title'){prepareCommander();return;}confirmBox(D.text.dialog_newgame_confirm,D.text.dialog_newgame_confirm_message,'help_confirmnew',()=>{tab='title';selected=null;prepareCommander();});}
   else if(id==='switch')confirmBox(D.text.dialog_switchgame_title,D.text.dialog_switchgame_message,'help_switchgame',switchGame);
   else if(id==='retire')confirmBox(D.text.dialog_retire_title,D.text.dialog_retire_message,'help_retire',()=>{F.openRetirement(s);F.respondRetirement(s,true);});
   else if(id==='options')overlay='options';
   else if(id==='shortcuts')overlay='shortcuts';
   else if(id==='scores')overlay='scores';
   else if(id==='clearscores')confirmBox(D.text.dialog_clearscores_title,D.text.dialog_clearscores_message,'help_cleartable',()=>{scores=[];try{localStorage.setItem('space-trader-high-scores-v1','[]');}catch{}});
   else if(id==='export')exportSave();
   else if(id==='import'){if(tab==='title'||s.ended||newCommander)$('save-file').click();else confirmBox('Import Save','This will overwrite your current game. Are you sure you wish to import a save?','help_reallyload',()=>$('save-file').click());}
   render();
 }
 // AboutDialog (dialog_about.xml); the .about-port block below the original text describes this port and is not in the original. The Play Store "Rate/Review" link is omitted: it reviews the Android app, not this port.
 function aboutDialog(){return `<section class="panel dialog native-about"><h2>${esc(D.text.dialog_about)}</h2><p class="about-title"><img src="${ASSETS.ic_launcher}" alt="">${esc(D.text.dialog_about_title.replace('%1$s',D.text.app_name).replace('%2$s','1.3.5'))}</p><p>${esc(D.text.dialog_about_author)}</p><p>${esc(D.text.dialog_about_author2||'Palm OS version copyright \u00a9 2000\u20132002 by Pieter Spronck')}</p><p>${esc(D.text.dialog_about_images)}</p><p>${esc(D.text.dialog_about_license)}</p><p><a href="${esc(D.text.dialog_about_url)}" target="_blank" rel="noopener">${esc(D.text.dialog_about_url)}</a></p><div class="about-port"><p class="about-port-title">Space Trader Classic /*APPVERSION*/</p><p>An unofficial web port of Russell Wolf's Android version 1.3.5 by lunchwine, also under the GPL. It aims to play exactly the same, adding only save import/export and following the system's light/dark setting.</p><p><a href="https://github.com/lunchwine/space-trader-classic" target="_blank" rel="noopener">github.com/lunchwine/space-trader-classic</a></p></div><div class="native-buttons"><button data-close-overlay>${esc(D.text.generic_ok)}</button></div></section>`;}
 function shortcutsDialog(){return `<section class="panel dialog shortcuts-dialog"><h2>${esc(D.text.dialog_shortcut_title)}</h2><p class="native-prompt">${esc(D.text.dialog_shortcut_prompt)}</p>${shortcuts.map((id,i)=>`<label class="native-label" for="shortcut-${i}">${esc(D.text['dialog_shortcut_'+(i+1)])}</label><select id="shortcut-${i}" class="native-spinner" data-shortcut-slot="${i}">${commands.map(([c,k])=>`<option value="${c}" ${c===id?'selected':''}>${k} ${D.text.dialog_shortcut_spacer} ${esc(D.text['shortcut_spinner_'+c])}</option>`).join('')}</select>`).join('')}<div class="native-buttons"><button data-close-overlay>${esc(D.text.generic_ok)}</button></div></section>`;}

 function titleScreen(){return `<section class="title-screen"><h2>Space Trader</h2><button data-start-commander aria-label="Start new commander"><img src="${ASSETS.title}" alt="Original Space Trader title artwork"></button><div class="title-version">Space Trader Classic v/*APPVERSION*/</div></section>`;}
 function prepareCommander(){newCommander={name:s.commanderName||D.text.name_commander||'Jameson',difficulty:s.difficulty,skills:{pilot:1,fighter:1,trader:1,engineer:1},random:!!s.randomQuestSystems,seed:''};overlay='newCommander';quantity=null;render();}
 // NewGameDialog (dialog_newgame.xml): OK only; the checks happen when OK is pressed (GameState.newCommanderFormHandleEvent).
 function newCommanderDialog(){const n=newCommander,remaining=20-Object.values(n.skills).reduce((a,b)=>a+b,0);return `<section class="panel dialog new-commander"><h2>${esc(D.text.dialog_newgame)}</h2><div class="commander-name"><label for="new-commander-name">Name</label><input id="new-commander-name" maxlength="30" value="${esc(n.name)}"></div><div class="difficulty-picker"><strong>Difficulty</strong><button data-level-step="-1" aria-label="Decrease difficulty">−</button><span>${D.difficulties[n.difficulty].label}</span><button data-level-step="1" aria-label="Increase difficulty">+</button></div><div class="points-row"><strong>Skill points</strong><span>${remaining}</span></div>${Object.entries(n.skills).map(([k,v])=>`<div class="skill-picker"><strong>${k[0].toUpperCase()+k.slice(1)}</strong><button data-skill="${k}" data-step="-1" aria-label="Decrease ${k}">−</button><span>${v}</span><button data-skill="${k}" data-step="1" aria-label="Increase ${k}">+</button></div>`).join('')}<label class="random-choice"><input id="new-random-quests" type="checkbox" ${n.random?'checked':''}>Randomize Quest Systems</label>${EXTRAS.galaxySeed?`<details class="advanced-new"><summary>Advanced</summary><label for="new-seed">Galaxy seed</label><input id="new-seed" type="text" inputmode="numeric" placeholder="Random" value="${esc(n.seed)}"><button data-balance-skills>Distribute evenly</button></details>`:''}<div class="native-buttons"><button data-import-commander>Import Save</button><button data-create-commander>${esc(D.text.generic_ok)}</button></div></section>`;}
 function newsRandom(a,b){let x=a>0?a:521288629,y=b>0?b:362436069;return n=>{x=(18000*(x&65535)+(x>>16))|0;y=(30903*(y&65535)+(y>>16))|0;return (((x<<16)+(y&65535))|0)%n<0?(((((x<<16)+(y&65535))|0)%n)+n):((((x<<16)+(y&65535))|0)%n);};}
 function newspaper(){const sys=s.systems[s.current],gov=D.governments.find(g=>g.id===sys.government),A=SpaceTraderPresentationData.arrays,rnd=newsRandom(s.current,s.days),format=(txt,args)=>{let i=0;return txt.replace(/%(?:(\d+)\$)?s/g,(_,n)=>args[n?Number(n)-1:i++]||'');},headlines=[],add=txt=>{if(txt&&headlines.length<5)headlines.push(txt.replace(/%%/g,'%'));};let real=false;
  for(const story of E.newsStories(s))if(story.id!=='CAUGHTLITTERING')add(format(story.text,story.args));
  const currentStatus=D.statuses.find(t=>t.id===sys.status);if(currentStatus.localHeadlineId!==-1)add(D.text[currentStatus.localHeadlineId]);
  if(s.policeScore<=-30)add(format(A.headline_villain[rnd(4)],[s.commanderName||'Commander',sys.name]));if(s.policeScore>=25)add(format(A.headline_hero[rnd(3)],[s.commanderName||'Commander']));
  for(const story of E.newsStories(s))if(story.id==='CAUGHTLITTERING')add(format(story.text,story.args));
  for(const other of s.systems)if(other.id!==sys.id&&(E.distance(sys,other)<=D.ships.find(t=>t.id===s.ship.type).fuelTanks||E.wormholeExists(s,sys.id,other.id))){if(other.special==='MOONFORSALE')add(format(D.text.newsevent_moonforsale,[other.name,s.systems[s.destinations.utopia].name]));if(other.special==='BUYTRIBBLE')add(format(D.text.newsevent_buytribble,[other.name]));if(other.status!=='UNEVENTFUL'&&rnd(100)<=6*sys.tech+10*(5-s.difficulty)){const status=D.statuses.find(t=>t.id===other.status);add(format(A.headline_remote[rnd(6)],[D.text[status.remoteHeadlineId],other.name]));real=true;}}
  if(!real){const shown=new Set();for(let i=0;i<=rnd(4);i++){const j=rnd(4);if(!shown.has(j)){add(A[gov.headlineId][j]);shown.add(j);}}}
  return {title:format(A[gov.mastheadId][s.current%3],[sys.name]),headlines};
 }
