   const screen=screenName(),locked=['encounter','result','notice','arrival','quest','ended','decision','orbit','arrest','purchase','personnel','banking','recovery','scoop','plunder','disposal','passenger','special','singularity','wildDeparture','rareDecision','retirement','quantity','scores','options','about','fuelBudget','repairBudget','newCommander','news','newsQuote','find','help','error','routes','loanAmount','repayAmount','shipImage','warpCosts','box','shortcuts','shipInfo','cheat','veryRareCheat','questsCheat'].includes(screen);
